import { createChart } from '../../core/utHelper';
import { EChartsType } from '../../../../src/echarts.all';

describe('scratch inverse time bandwidth', function () {
    it('compare', function () {
        const data = [
            ['2020-01-01', 1], ['2020-01-02', 2], ['2020-01-03', 3], ['2020-01-04', 4]
        ];
        function widths(inverse: boolean) {
            const chart = createChart({ width: 500, height: 400 });
            chart.setOption({
                xAxis: { type: 'time', inverse: inverse },
                yAxis: {},
                series: [{ type: 'bar', data: data }]
            });
            const series = (chart as any).getModel().getSeries()[0];
            const d = series.getData();
            const out: any = { bandWidth: d.getLayout('bandWidth'), items: [] as any[] };
            for (let i = 0; i < d.count(); i++) {
                out.items.push(d.getItemLayout(i));
            }
            chart.dispose();
            return out;
        }
        const a = widths(false);
        const b = widths(true);
        console.log('normal bandWidth', a.bandWidth, 'w', a.items.map((x: any) => x && x.width));
        console.log('inverse bandWidth', b.bandWidth, 'w', b.items.map((x: any) => x && x.width));
        console.log('normal x', a.items.map((x: any) => x && x.x));
        console.log('inverse x', b.items.map((x: any) => x && x.x));
    });
});
