if (current.length < next.length) {
    const padded = createFloat32Array(next.length);
    for (let i = 0; i < current.length; i++) { padded[i] = current[i]; }
    for (let i = current.length; i < next.length; i++) { padded[i] = next[i]; }
    current = padded;
}
```
(and the same for `stackedOnCurrent` vs `stackedOnNext`).
