input.new_string:
    it('should keep the labels of both sides separated on x axis', function () {
        const data: {name: string, value: number}[] = [{ name: 'Dominant', value: 1000 }];
        for (let i = 0; i < 40; i++) {
            data.push({ name: 'Tiny ' + i, value: 1 });
        }

        chart.setOption({
            series: [{
                type: 'pie',
                radius: '50%',
                startAngle: 180,
                data
            }]
        });

        const layout0 = getSeriesData(chart).getItemLayout(0);
        const cx = layout0.cx;
        const cy = layout0.cy;
        const labels = getLabelStates(chart);

        // The labels laid out on the ellipse curve should never be moved
        // across (or onto) the center of the pie.
        for (let i = 0; i < labels.length; i++) {
            expect(Math.abs(labels[i].x - cx)).toBeGreaterThan(0);
        }

        // Within one side of one semi the labels form an ellipse curve: the
        // farther a label is from the center on the y axis, the closer it is
        // to the center on the x axis. A label that was clamped to `cx`
        // would break that monotonicity (and its label line would be drawn
        // across the pie body).
        const leftBottom = labels
            .filter(item => item.x < cx && item.y > cy)
            .sort((a, b) => a.y - b.y);
        expect(leftBottom.length).toBeGreaterThan(2);
        for (let i = 1; i < leftBottom.length; i++) {
            expect(leftBottom[i].x).toBeGreaterThanOrEqual(leftBottom[i - 1].x);
        }
    });
});

