 */
function resetSilentForRegion(
    el: Element,
    regionModel: RegionModel
): void {
    // Assign it unconditionally, because the els are not necessarily recreated
    // on each render (the els of an SVG map are pooled and reused), and thus a
    // `silent` that is no longer specified has to be reset.
    // @ts-ignore FIXME:TS fix the "compatible with each other"?
    el.silent = !!regionModel.get('silent');
}

