import { EChartsType, registerMap } from '../../../../../src/echarts.all';
import { createChart, removeChart } from '../../../core/utHelper';
import {
    makeGeoJSONFeature, getRegionEl, registerSVGMap, SVG_MAP_SOURCE
} from '../../../core/mapSilentHelper';

describe('geo region silent', function () {

    let chart: EChartsType;

    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        removeChart(chart);
    });

    it('should only silence the regions that declare `silent` on GeoJSON maps', function () {
        registerMap('ut-geo-silent', {
            type: 'FeatureCollection',
            features: [
                makeGeoJSONFeature('AAA', 0),
                makeGeoJSONFeature('BBB', 10)
            ]
        } as any);

        chart.setOption({
            geo: {
                map: 'ut-geo-silent',
                regions: [{
                    name: 'AAA',
                    silent: true
                }]
            }
        });

        expect(getRegionEl(chart, 'geo', 'AAA').silent).toBe(true);
        // The neighbour region keeps responding to events.
        expect(getRegionEl(chart, 'geo', 'BBB').silent).toBe(false);
    });

    it('should reset `silent` when it is no longer declared on GeoJSON maps', function () {
        registerMap('ut-geo-silent-reset', {
            type: 'FeatureCollection',
            features: [
                makeGeoJSONFeature('AAA', 0),
                makeGeoJSONFeature('BBB', 10)
            ]
        } as any);

        chart.setOption({
            geo: {
                map: 'ut-geo-silent-reset',
                regions: [{ name: 'AAA', silent: true }]
            }
        });
        expect(getRegionEl(chart, 'geo', 'AAA').silent).toBe(true);

        chart.setOption({
            geo: {
                map: 'ut-geo-silent-reset',
                regions: [{ name: 'AAA' }]
            }
        }, true);
        expect(getRegionEl(chart, 'geo', 'AAA').silent).toBe(false);
    });

    it('should support `silent` on SVG backed regions', function () {
        registerSVGMap('ut-geo-silent-svg');

