import { EChartsType, registerMap } from '../../../../../src/echarts.all';
import { createChart, getECModel, getGraphicElements, removeChart } from '../../../core/utHelper';
import Displayable from 'zrender/src/graphic/Displayable';
import Group from 'zrender/src/graphic/Group';
import MapSeries from '../../../../../src/chart/map/MapSeries';

function makeFeature(name: string, x0: number, echartsStyle?: any) {
    const feature = {
        type: 'Feature',
        properties: {
            name: name
        },
        geometry: {
            type: 'Polygon',
            coordinates: [[[x0, 0], [x0, 10], [x0 + 10, 10], [x0 + 10, 0], [x0, 0]]]
        }
    } as any;
    if (echartsStyle) {
        feature.properties.echartsStyle = echartsStyle;
    }
    return feature;
}

function getRegionPathStyle(chart: EChartsType, regionName: string): Displayable['style'] {
    const seriesModel = getECModel(chart).getSeriesByIndex(0) as MapSeries;
    const data = seriesModel.getData();
    const el = data.getItemGraphicEl(data.indexOfName(regionName));
    const path = el && (el as Group).childAt(0) as Displayable;
    return path && path.style;
}

describe('series.map geoJSON region style', function () {

    let chart: EChartsType;

    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        removeChart(chart);
    });

    it('should pick up `echartsStyle` for regions that have no data item', function () {
        registerMap('ut-map-geojson-style', {
            type: 'FeatureCollection',
            features: [
                makeFeature('AAA', 0, { itemStyle: { areaColor: 'red' } }),
                makeFeature('BBB', 10)
            ]
        } as any);
=== getViewGroup ===
export function getViewGroup(
    chart: EChartsType,
    mainType: ComponentMainType,
    index?: number
): Group {
    const component = getECModel(chart).getComponent(mainType, index);
    return component ? chart[
        mainType === 'series' ? '_chartsMap' : '_componentsMap'
    ][component.__viewId].group : null;
}

export function getECModel(chart: EChartsType): GlobalModel {
    // @ts-ignore
    return chart.getModel();
}

