import { getGraphicElements } from './utHelper';
import Element from 'zrender/src/Element';

/**
 * A minimal GeoJSON region, a 10x10 square placed at `x0`.
 */
export function makeGeoJSONFeature(name: string, x0: number): unknown {
    return {
        type: 'Feature',
        properties: {
            name: name
        },
        geometry: {
            type: 'Polygon',
            coordinates: [[[x0, 0], [x0, 10], [x0 + 10, 10], [x0 + 10, 0], [x0, 0]]]
        }
    };
}

/**
 * An SVG map with the same two named regions as the GeoJSON above, so that
 * both resource types can be asserted with the same expectations.
 */
export const SVG_MAP_SOURCE = [
    '<svg width="100" height="100" viewBox="0 0 100 100"'
        + ' xmlns="http://www.w3.org/2000/svg">',
    '<rect name="AAA" x="0" y="0" width="40" height="40" />',
    '<rect name="BBB" x="50" y="0" width="40" height="40" />',
    '</svg>'
].join('');

export function registerSVGMap(mapName: string): void {
    registerMap(mapName, { svg: SVG_MAP_SOURCE } as any);
}

/**
 * The el that hosts a region of a `geo` component, that is, the el that the
 * region event data and the region interaction settings are applied to. It is
 * the region group for a GeoJSON map, and the named el for an SVG map.
 */
export function getGeoRegionEl(chart: EChartsType, regionName: string): Element {
    const els = getGraphicElements(chart, 'geo', 0);
    for (let i = 0; i < els.length; i++) {
        const eventData = getECData(els[i]).eventData;
        if (eventData && eventData.name === regionName) {
            return els[i];
        }
    }
    return null;
}

/**
 * The el that hosts a region of a `series.map`. Unlike `geo`, a map series
 * mounts the region el on its data instead of packaging event data on it.
 */
export function getMapSeriesRegionEl(chart: EChartsType, regionName: string): Element {
    const seriesModel = getECModel(chart).getSeriesByIndex(0);
    const data = seriesModel.getData();
    return data.getItemGraphicEl(data.indexOfName(regionName));
}

