import { EChartsType, registerMap } from '../../../../../src/echarts.all';
import { createChart, removeChart } from '../../../core/utHelper';
import {
    makeGeoJSONFeature, getGeoRegionEl, registerSVGMap, SVG_MAP_SOURCE
} from '../../../core/mapSilentHelper';

describe('geo region silent', function () {

    let chart: EChartsType;

    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        removeChart(chart);
    });

    it('should only silence the regions that declare `silent` on GeoJSON maps', function () {
        registerMap('ut-geo-silent', {
            type: 'FeatureCollection',
            features: [
                makeGeoJSONFeature('AAA', 0),
                makeGeoJSONFeature('BBB', 10)
            ]
        } as any);

        chart.setOption({
            geo: {
                map: 'ut-geo-silent',
                regions: [{
                    name: 'AAA',
                    silent: true
                }]
            }
        });

        expect(getGeoRegionEl(chart, 'AAA').silent).toBe(true);
        // The neighbour region keeps responding to events.
        expect(getGeoRegionEl(chart, 'BBB').silent).toBe(false);
    });

    it('should reset `silent` when it is no longer declared on GeoJSON maps', function () {
        registerMap('ut-geo-silent-reset', {
            type: 'FeatureCollection',
            features: [
                makeGeoJSONFeature('AAA', 0),
                makeGeoJSONFeature('BBB', 10)
            ]
        } as any);

        chart.setOption({
            geo: {
                map: 'ut-geo-silent-reset',
                regions: [{ name: 'AAA', silent: true }]
            }
        });
        expect(getGeoRegionEl(chart, 'AAA').silent).toBe(true);

        chart.setOption({
            geo: {
                map: 'ut-geo-silent-reset',
                regions: [{ name: 'AAA' }]
            }
        }, true);
        expect(getGeoRegionEl(chart, 'AAA').silent).toBe(false);
    });

    it('should support `silent` on SVG backed regions', function () {
        registerSVGMap('ut-geo-silent-svg');

        chart.setOption({
            geo: {
                map: 'ut-geo-silent-svg',
                regions: [{ name: 'AAA', silent: true }]
            }
        });

        expect(getGeoRegionEl(chart, 'AAA').silent).toBe(true);
        expect(getGeoRegionEl(chart, 'BBB').silent).toBe(false);

        // The SVG els are reused across renders, so a `silent` that is no
        // longer specified has to be reset rather than kept.
        chart.setOption({
            geo: {
                map: 'ut-geo-silent-svg',
                regions: [{ name: 'AAA' }]
            }
        });
        expect(getGeoRegionEl(chart, 'AAA').silent).toBe(false);
        expect(getGeoRegionEl(chart, 'BBB').silent).toBe(false);
    });

    it('should not leak `silent` into another chart that reuses the SVG source', function () {
        registerSVGMap('ut-geo-silent-svg-pool');

        chart.setOption({
            geo: {
                map: 'ut-geo-silent-svg-pool',
                regions: [{ name: 'AAA', silent: true }]
            }
        });
        expect(getGeoRegionEl(chart, 'AAA').silent).toBe(true);

        // Disposing returns the parsed SVG graphic into the resource pool.
        removeChart(chart);

        chart = createChart();
        chart.setOption({
            geo: {
                map: 'ut-geo-silent-svg-pool'
            }
        });
        expect(getGeoRegionEl(chart, 'AAA').silent).toBe(false);
    });

    it('SVG_MAP_SOURCE should declare the regions the tests rely on', function () {
        expect(SVG_MAP_SOURCE.indexOf('name="AAA"') >= 0).toBe(true);
        expect(SVG_MAP_SOURCE.indexOf('name="BBB"') >= 0).toBe(true);
    });
});

