    });

    it('should only silence the data items that declare `silent`', function () {
        registerMap('ut-map-silent', {
            type: 'FeatureCollection',
            features: [
                makeGeoJSONFeature('AAA', 0),
                makeGeoJSONFeature('BBB', 10)
            ]
        } as any);

        chart.setOption({
            series: [{
                type: 'map',
                map: 'ut-map-silent',
                data: [
                    { name: 'AAA', value: 1, silent: true },
                    { name: 'BBB', value: 2 }
                ]
            }]
        });

        expect(getMapSeriesRegionEl(chart, 'AAA').silent).toBe(true);
        // The neighbour region keeps responding to events.
        expect(getMapSeriesRegionEl(chart, 'BBB').silent).toBe(false);
        expect(isSilentInChain(getMapSeriesRegionEl(chart, 'BBB'))).toBe(false);
    });

    it('should keep the region visible while it is silent', function () {
        registerMap('ut-map-silent-visual', {
            type: 'FeatureCollection',
            features: [
                makeGeoJSONFeature('AAA', 0),
                makeGeoJSONFeature('BBB', 10)
            ]
        } as any);

        chart.setOption({
            series: [{
                type: 'map',
                map: 'ut-map-silent-visual',
                label: { show: true },
                data: [
                    { name: 'AAA', value: 1, silent: true, itemStyle: { areaColor: 'red' } },
                    { name: 'BBB', value: 2 }
                ]
            }]
        });

        const el = getMapSeriesRegionEl(chart, 'AAA');
        expect(el.ignore).toBeFalsy();
        // The visual is untouched: the compound path is still filled as
        // specified, and the label is still there.
        const path = (el as any).childAt(0);
        expect(path.style.fill).toEqual('red');
        expect(path.getTextContent()).not.toBeNull();
    });

    it('should reset `silent` when the map data is refreshed without it', function () {
        registerMap('ut-map-silent-refresh', {
            type: 'FeatureCollection',
            features: [
                makeGeoJSONFeature('AAA', 0),
                makeGeoJSONFeature('BBB', 10)
            ]
        } as any);

        function setData(silentAAA: boolean) {
            chart.setOption({
                series: [{
                    type: 'map',
                    map: 'ut-map-silent-refresh',
                    data: [
                        silentAAA
                            ? { name: 'AAA', value: 1, silent: true }
                            : { name: 'AAA', value: 1 },
                        { name: 'BBB', value: 2 }
                    ]
                }]
            }, true);
        }

        setData(true);
        expect(getMapSeriesRegionEl(chart, 'AAA').silent).toBe(true);

        setData(false);
        expect(getMapSeriesRegionEl(chart, 'AAA').silent).toBe(false);
        expect(getMapSeriesRegionEl(chart, 'BBB').silent).toBe(false);
    });

    it('should support `silent` on SVG backed regions and reset it on refresh', function () {
        registerSVGMap('ut-map-silent-svg');

        function setData(silentAAA: boolean) {
            chart.setOption({
                series: [{
                    type: 'map',
                    map: 'ut-map-silent-svg',
                    data: [
                        silentAAA
                            ? { name: 'AAA', value: 1, silent: true }
                            : { name: 'AAA', value: 1 },
                        { name: 'BBB', value: 2 }
                    ]
                }]
            });
        }

        setData(true);
        expect(getMapSeriesRegionEl(chart, 'AAA').silent).toBe(true);
        expect(getMapSeriesRegionEl(chart, 'BBB').silent).toBe(false);

        // The SVG els are reused across renders, so a `silent` that is no
        // longer specified has to be reset rather than kept.
        setData(false);
        expect(getMapSeriesRegionEl(chart, 'AAA').silent).toBe(false);
        expect(getMapSeriesRegionEl(chart, 'BBB').silent).toBe(false);
    });
});

