import { EChartsType, registerMap } from '../../../../../src/echarts.all';
import { createChart, removeChart } from '../../../core/utHelper';
import { getECData } from '../../../../../src/util/innerStore';
import Element from 'zrender/src/Element';
import {
    makeGeoJSONFeature, getRegionEl, registerSVGMap
} from '../../../core/mapSilentHelper';

describe('series map region silent', function () {

    let chart: EChartsType;

    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        removeChart(chart);
    });

    it('should only silence the data items that declare `silent`', function () {
        registerMap('ut-map-silent', {
            type: 'FeatureCollection',
            features: [
                makeGeoJSONFeature('AAA', 0),
                makeGeoJSONFeature('BBB', 10)
            ]
        } as any);

        chart.setOption({
            series: [{
                type: 'map',
                map: 'ut-map-silent',
                data: [
                    { name: 'AAA', value: 1, silent: true },
                    { name: 'BBB', value: 2 }
                ]
            }]
        });

        expect(getRegionEl(chart, 'series', 'AAA').silent).toBe(true);
        expect(getRegionEl(chart, 'series', 'BBB').silent).toBe(false);
    });

    it('should keep the label of a silent region silent as well', function () {
        registerMap('ut-map-silent-label', {
            type: 'FeatureCollection',
            features: [
                makeGeoJSONFeature('AAA', 0),
                makeGeoJSONFeature('BBB', 10)
            ]
        } as any);

        chart.setOption({
            series: [{
                type: 'map',
                map: 'ut-map-silent-label',
                label: { show: true },
                data: [
                    { name: 'AAA', value: 1, silent: true },
                    { name: 'BBB', value: 2 }
                ]
            }]
        });

        // zrender resolves `silent` through the whole ancestor chain, so the
        // label hosted by the region also stops responding to events.
        let el: Element = getRegionEl(chart, 'series', 'AAA');
        let silentInChain = false;
        while (el) {
            silentInChain = silentInChain || !!el.silent;
            el = el.parent;
        }
        expect(silentInChain).toBe(true);
    });

    it('should reset `silent` when the map data is refreshed without it', function () {
        registerMap('ut-map-silent-refresh', {
            type: 'FeatureCollection',
            features: [
                makeGeoJSONFeature('AAA', 0),
                makeGeoJSONFeature('BBB', 10)
            ]
        } as any);

        function setData(silentAAA: boolean) {
            chart.setOption({
                series: [{
                    type: 'map',
                    map: 'ut-map-silent-refresh',
                    data: [
                        silentAAA
                            ? { name: 'AAA', value: 1, silent: true }
                            : { name: 'AAA', value: 1 },
                        { name: 'BBB', value: 2 }
                    ]
                }]
            }, true);
        }

        setData(true);
        expect(getRegionEl(chart, 'series', 'AAA').silent).toBe(true);

        setData(false);
        expect(getRegionEl(chart, 'series', 'AAA').silent).toBe(false);
        expect(getRegionEl(chart, 'series', 'BBB').silent).toBe(false);
    });

    it('should support `silent` on SVG backed regions and reset it on refresh', function () {
        registerSVGMap('ut-map-silent-svg');

        function setData(silentAAA: boolean) {
            chart.setOption({
                series: [{
                    type: 'map',
                    map: 'ut-map-silent-svg',
                    data: [
                        silentAAA
                            ? { name: 'AAA', value: 1, silent: true }
                            : { name: 'AAA', value: 1 },
                        { name: 'BBB', value: 2 }
                    ]
                }]
            });
        }

        setData(true);
        expect(getRegionEl(chart, 'series', 'AAA').silent).toBe(true);
        expect(getRegionEl(chart, 'series', 'BBB').silent).toBe(false);

        setData(false);
        expect(getRegionEl(chart, 'series', 'AAA').silent).toBe(false);
        expect(getRegionEl(chart, 'series', 'BBB').silent).toBe(false);
    });

    it('should not change the event data of a silent region', function () {
        registerMap('ut-map-silent-eventdata', {
            type: 'FeatureCollection',
            features: [
                makeGeoJSONFeature('AAA', 0),
                makeGeoJSONFeature('BBB', 10)
            ]
        } as any);

        chart.setOption({
            series: [{
                type: 'map',
                map: 'ut-map-silent-eventdata',
                data: [
                    { name: 'AAA', value: 1, silent: true },
                    { name: 'BBB', value: 2 }
                ]
            }]
        });

        // The region keeps its visual and its identity, it only stops
        // receiving events.
        const el = getRegionEl(chart, 'series', 'AAA');
        expect(getECData(el).eventData.name).toEqual('AAA');
        expect(el.ignore).toBeFalsy();
    });
});

