                    renderMode: renderMode || 'html'
                },
                xAxis: {
                    type: 'category',
                    data: ['A', 'B']
                },
                yAxis: {},
                series: [{
                    type: 'bar',
                    name: 'S1',
                    data: [11, 22]
                }]
            };
        }

        function getTooltipView(chart: EChartsType): any {
            const componentsMap = (chart as any)._componentsMap;
            let found: any = null;
            for (const key in componentsMap) {
                if (componentsMap[key] && componentsMap[key].type === 'tooltip') {
                    found = componentsMap[key];
                }
            }
            return found;
        }

        it('should not throw when setOption with notMerge and showTip', function () {
            expect(function () {
                chart.setOption(makeOption(), true);
                chart.setOption(makeOption(), true);
                chart.dispatchAction({
                    type: 'showTip',
                    seriesIndex: 0,
                    dataIndex: 0
                });
            }).not.toThrow();

            const tooltipEl = getTooltipEl(chart);
            expect(tooltipEl).not.toBeNull();
            expect(tooltipEl.innerHTML === '').toBe(false);
            // `show()` writes the initial center coord into the style, so assert
            // that `moveTo` actually repositioned the new tooltip layer
            // afterwards instead of only that the style is non-empty.
            expect(tooltipEl.style.left).not.toEqual('250px');
            expect(tooltipEl.style.top).not.toEqual('200px');
            expect(parseFloat(tooltipEl.style.left)).not.toBeNaN();
            expect(parseFloat(tooltipEl.style.top)).not.toBeNaN();
        });

        it('should not throw when the tooltip layer is disposed by notMerge before showing', function () {
            jest.useFakeTimers();
            try {
                // `showDelay` defers `_showTooltipContent` (which updates the
                // content size and position) to a timer. The tooltip layer that
                // is captured by the timer is disposed by the `notMerge`
                // `setOption` below.
                chart.setOption(makeOption(100), true);
                chart.dispatchAction({
                    type: 'showTip',
                    seriesIndex: 0,
                    dataIndex: 0
                });
                chart.setOption(makeOption(100), true);

                expect(function () {
                    jest.advanceTimersByTime(500);
                }).not.toThrow();
            }
            finally {
                jest.useRealTimers();
            }
        });

        it('should clear the pending timers of the disposed tooltip view', function () {
            jest.useFakeTimers();
            try {
                chart.setOption(makeOption(100), true);
                chart.dispatchAction({
                    type: 'showTip',
                    seriesIndex: 0,
                    dataIndex: 0
                });

                const oldView = getTooltipView(chart);
                expect(oldView._showTimout).not.toBeNull();

                chart.setOption(makeOption(100), true);

                // The disposed view must not be driven by its own timers any more.
                expect(oldView._showTimout).toBeNull();
                expect(oldView._refreshUpdateTimeout).toBeNull();
                expect(getTooltipView(chart)).not.toBe(oldView);
            }
            finally {
                jest.useRealTimers();
            }
        });

        it('should not leave a ghost tooltip in richText mode', function () {
            jest.useFakeTimers();
            try {
                chart.setOption(makeOption(100, 'richText'), true);
                chart.dispatchAction({
                    type: 'showTip',
                    seriesIndex: 0,
                    dataIndex: 0
                });

                const oldContent = getTooltipView(chart)._tooltipContent;

                chart.setOption(makeOption(100, 'richText'), true);

                expect(function () {
                    jest.advanceTimersByTime(500);
                }).not.toThrow();

                // The content of the disposed view must not be (re)added to the
                // zrender instance of the live chart.
                expect(oldContent.el && (oldContent.el as any).__zr).toBeFalsy();
            }
            finally {
                jest.useRealTimers();
            }
        });
    });
});

