import { EChartsType } from '../../../../../src/echarts';
import { createChart } from '../../../core/utHelper';

/**
 * Find the tooltip content DOM created by `TooltipHTMLContent`.
 */
function getTooltipEl(chart: EChartsType): HTMLElement {
    const children = chart.getDom().children;
    for (let i = 0; i < children.length; i++) {
        const child = children[i] as HTMLElement;
        if ((child as any).domBelongToZr) {
            return child;
        }
    }
    return null;
}

describe('component/tooltip', function () {

    let chart: EChartsType;

    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        chart.dispose();
    });

    describe('legend name XSS', function () {

        const XSS_NAME = '<img src="x" onerror="window.__ec_xss_flag__ = true" />';

        function createLegendTooltipChart(name: string) {
            chart.setOption({
                tooltip: {},
                legend: {
                    tooltip: {
                        show: true
                    }
                },
                xAxis: {
                    type: 'category',
                    data: ['A', 'B']
                },
                yAxis: {},
                series: [{
                    type: 'bar',
                    name: name,
                    data: [1, 2]
                }]
            });
            chart.dispatchAction({
                type: 'showTip',
                legendIndex: 0,
                name: name
            });
        }

        it('should escape html in legend name', function () {
            createLegendTooltipChart(XSS_NAME);

            const tooltipEl = getTooltipEl(chart);
            expect(tooltipEl).not.toBeNull();

            const html = tooltipEl.innerHTML;
            // The html string should be escaped rather than being live markup.
            expect(html.indexOf('&lt;img') >= 0).toBe(true);
            expect(html.indexOf('<img') < 0).toBe(true);
            expect(tooltipEl.querySelector('img')).toBeNull();
            // It's displayed as plain text.
            expect(tooltipEl.textContent.indexOf(XSS_NAME) >= 0).toBe(true);
        });

        it('should not encode the name repeatedly', function () {
            createLegendTooltipChart(XSS_NAME);
            // Show the tooltip of the same legend item again.
            chart.dispatchAction({
                type: 'showTip',
                legendIndex: 0,
                name: XSS_NAME
            });

            const html = getTooltipEl(chart).innerHTML;
            expect(html.indexOf('&amp;lt;') < 0).toBe(true);
            expect(getTooltipEl(chart).textContent.indexOf(XSS_NAME) >= 0).toBe(true);
        });

        it('should keep normal legend name working', function () {
            createLegendTooltipChart('Sales');

            const tooltipEl = getTooltipEl(chart);
            expect(tooltipEl.innerHTML.indexOf('Sales') >= 0).toBe(true);
            expect(tooltipEl.textContent.indexOf('Sales') >= 0).toBe(true);
        });

        it('should not break richText render mode', function () {
            expect(function () {
                chart.setOption({
                    tooltip: {
                        renderMode: 'richText'
                    },
                    legend: {
                        tooltip: {
                            show: true
                        }
                    },
                    xAxis: {
                        type: 'category',
                        data: ['A', 'B']
                    },
                    yAxis: {},
                    series: [{
                        type: 'bar',
                        name: XSS_NAME,
                        data: [1, 2]
                    }]
                }, true);
                chart.dispatchAction({
                    type: 'showTip',
                    legendIndex: 0,
                    name: XSS_NAME
                });
            }).not.toThrow();
        });
    });

    describe('textStyle lineHeight', function () {

        function createLineHeightChart(lineHeight?: number) {
            chart.setOption({
                tooltip: {
                    trigger: 'axis',
                    textStyle: lineHeight != null ? { lineHeight: lineHeight } : {}
                },
                xAxis: {
                    type: 'category',
                    data: ['A', 'B']
                },
                yAxis: {},
                series: [{
                    type: 'line',
                    name: 'S1',
                    data: [11, 22]
                }, {
                    type: 'line',
                    name: 'S2',
                    data: [33, 44]
                }]
            }, true);
            chart.dispatchAction({
                type: 'showTip',
                seriesIndex: 0,
                dataIndex: 0
            });
        }

        it('should apply textStyle.lineHeight on the default tooltip content', function () {
            createLineHeightChart(30);

            const tooltipEl = getTooltipEl(chart);
            expect(tooltipEl).not.toBeNull();
            // The content of the default tooltip is composed of blocks, each of
            // them should use the specified line height instead of `line-height: 1`.
            expect(tooltipEl.innerHTML.indexOf('line-height:30px') >= 0).toBe(true);
            expect(tooltipEl.innerHTML.indexOf('line-height:1;') < 0).toBe(true);
            // The tooltip container as well.
            expect(tooltipEl.style.lineHeight).toBe('30px');
        });

        it('should keep the default line height if not specified', function () {
            createLineHeightChart();

            const tooltipEl = getTooltipEl(chart);
            expect(tooltipEl.innerHTML.indexOf('line-height:1;') >= 0).toBe(true);
            // 1.5 * fontSize(14)
            expect(tooltipEl.style.lineHeight).toBe('21px');
            // Other text styles keep working.
            expect(tooltipEl.innerHTML.indexOf('font-size:14px') >= 0).toBe(true);
            expect(tooltipEl.innerHTML.indexOf('color:#666') >= 0).toBe(true);
        });
    });

    describe('setOption with notMerge', function () {

        function makeOption(showDelay?: number) {
            return {
                tooltip: {
                    showDelay: showDelay || 0
                },
                xAxis: {
                    type: 'category',
                    data: ['A', 'B']
                },
                yAxis: {},
                series: [{
                    type: 'bar',
                    name: 'S1',
                    data: [11, 22]
                }]
            };
        }

        it('should not throw when setOption with notMerge and showTip', function () {
            expect(function () {
                chart.setOption(makeOption(), true);
                chart.setOption(makeOption(), true);
                chart.dispatchAction({
                    type: 'showTip',
                    seriesIndex: 0,
                    dataIndex: 0
                });
            }).not.toThrow();

            // Position is still updated on the new tooltip layer.
            const tooltipEl = getTooltipEl(chart);
            expect(tooltipEl).not.toBeNull();
            expect(tooltipEl.innerHTML === '').toBe(false);
            expect(tooltipEl.style.left === '' && tooltipEl.style.top === '').toBe(false);
        });

        it('should not throw when the tooltip layer is disposed by notMerge before showing', function () {
            jest.useFakeTimers();
            try {
                // `showDelay` defers `_showTooltipContent` (which updates the
                // content size and position) to a timer. The tooltip layer that
                // is captured by the timer is disposed by the `notMerge`
                // `setOption` below.
                chart.setOption(makeOption(100), true);
                chart.dispatchAction({
                    type: 'showTip',
                    seriesIndex: 0,
                    dataIndex: 0
                });
                chart.setOption(makeOption(100), true);

                expect(function () {
                    jest.advanceTimersByTime(500);
                }).not.toThrow();
            }
            finally {
                jest.useRealTimers();
            }
        });
    });
});

