*/

import { createChart } from '../../../core/utHelper';

const DAY = 24 * 3600 * 1000;
const T0 = Date.UTC(2024, 0, 1);
const WIDTH = 500;

interface BarLayoutInfo {
    bandWidth: number
    width: number
    x: number[]
    scaleSpan: number
}

function layoutOf(inverse: boolean, count?: number): BarLayoutInfo {
    count = count || 3;
    const data: number[][] = [];
    for (let i = 0; i < count; i++) {
        data.push([T0 + i * DAY, i + 1]);
    }

    const chart = createChart({ width: WIDTH, height: 400 });
    chart.setOption({
        useUTC: true,
        animation: false,
        grid: { left: 0, right: 0, top: 0, bottom: 0 },
        xAxis: { type: 'time', inverse: inverse },
        yAxis: { type: 'value' },
        series: [{ type: 'bar', data: data }]
    });

    const series = (chart as any).getModel().getSeriesByIndex(0);
    const seriesData = series.getData();
    const scaleExtent = series.coordinateSystem.getBaseAxis().scale.getExtent();
    const x: number[] = [];
    for (let i = 0; i < count; i++) {
        x.push(seriesData.getItemLayout(i).x);
    }
    const result = {
        bandWidth: seriesData.getLayout('bandWidth') as number,
        width: seriesData.getItemLayout(0).width as number,
        x: x,
        scaleSpan: scaleExtent[1] - scaleExtent[0]
    };
    chart.dispose();
    return result;
}

describe('bar_bandWidth_inversedTimeAxis', function () {

    it('should calculate the same bandWidth on an inversed and a normal time axis', function () {
        const normal = layoutOf(false);
        const inversed = layoutOf(true);

        expect(normal.bandWidth).toBeGreaterThan(0);
        expect(inversed.bandWidth).toBeCloseTo(normal.bandWidth, 4);
        expect(inversed.width).toBeCloseTo(normal.width, 4);
        // The scale extent is expanded to make room for the half bars that
        // stick out past the first and the last data point, in both directions.
        expect(inversed.scaleSpan).toBeCloseTo(normal.scaleSpan, 0);
        expect(inversed.scaleSpan).toBeGreaterThan((normal.x.length - 1) * DAY);
    });

    it('should keep bars inside the grid and mirrored on an inversed time axis', function () {
        const normal = layoutOf(false);
        const inversed = layoutOf(true);

        for (let i = 0; i < normal.x.length; i++) {
            // Reversing the axis mirrors the bars instead of distorting them.
            expect(inversed.x[i]).toBeCloseTo(
                WIDTH - normal.x[normal.x.length - 1 - i] - normal.width, 4
            );
            expect(inversed.x[i]).toBeGreaterThanOrEqual(-1e-6);
            expect(inversed.x[i] + inversed.width).toBeLessThanOrEqual(WIDTH + 1e-6);
        }
    });

    it('should keep the non-inversed time axis layout unchanged', function () {
        // The bars of a 3-point daily series fill the grid evenly: one band per
        // day plus a half band of padding on each side.
        const normal = layoutOf(false);
        expect(normal.bandWidth).toBeCloseTo(WIDTH / 3, 4);
        for (let i = 1; i < normal.x.length; i++) {
            expect(normal.x[i] - normal.x[i - 1]).toBeCloseTo(normal.bandWidth, 4);
        }
    });

    it('should keep working with more data points on an inversed time axis', function () {
        const normal = layoutOf(false, 10);
        const inversed = layoutOf(true, 10);
        expect(inversed.bandWidth).toBeCloseTo(normal.bandWidth, 4);
        expect(inversed.width).toBeCloseTo(normal.width, 4);
    });
});

